/* Presentation fixtures only: no game imports, evaluator, RNG, storage or network calls. */
const asset='../../public/assets/handdrawn-p08/cards/';
const fixtures=[
{id:'mantangcai',name:'满堂彩',rarity:'普通',mark:'●',stars:4,word:'很合用',route:'契合成组',combo:'无需搭档',dots:'',hook:'成组就加热度',conditions:[['✓','成组主手 · 样例为葫芦'],['✓','直接加热，不依赖重触发搭档']],note:'卡牌效果：任何成组牌型，整手热度 +90。推荐星数仅用于本页展示。'},
{id:'e08',name:'包场',rarity:'稀有',mark:'✦',stars:2,word:'暂缓',route:'各路线通用',combo:'门槛未满足',dots:'○',hook:'购后 18 金 / 需 20 金',conditions:[['○','购后只余 18 金，尚缺 2 金'],['✓','任何路线均可使用']],note:'卡牌效果：当前金币至少 20 时，整手倍率 ×1.8。通用不等于当前适合，稀有度不随金币改变。'},
{id:'b06',name:'再说一遍',rarity:'稀有',mark:'✦',stars:3,word:'待搭配',route:'契合成组',combo:'已满足 1/2',dots:'●○',hook:'缺「一束光」搭档',conditions:[['✓','成组主手 · 三张 K 在前'],['○','缺一束光 · 补充逐牌热度来源']],note:'再说一遍让成组主手中最大同点组的有效牌再计一次。一束光可让合格主手的首张有效计分牌再次获得 +15 热度；这里只呈现组合关系，不估算整手收益。'}
];
let complete=false;const selected=new Set();
const star=(filled)=>`<svg class="${filled?'filled':''}" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.4 14.9 8.6 21.8 9.4 16.7 14.1 18.1 21 12 17.5 5.9 21 7.3 14.1 2.2 9.4 9.1 8.6Z"/></svg>`;
const stars=n=>`<span class="stars" role="img" aria-label="推荐指数 ${n} 星，满分 5 星">${Array.from({length:5},(_,i)=>star(i<n)).join('')}</span>`;
function current(){return fixtures.map(c=>c.id==='b06'&&complete?{...c,stars:5,word:'极佳契合',combo:'已满足 2/2',dots:'●●',hook:'模拟齐备 · 逐牌再计',conditions:[['✓','成组主手 · 三张 K 在前'],['✓','已有一束光 · 首张 K 可再获热度']]}:c);}
function render(){const opened=new Set([...document.querySelectorAll('details[open]')].map(e=>e.dataset.id));document.querySelector('#cards').innerHTML=current().map(c=>`<article class="card ${selected.has(c.id)?'selected':''}" data-card="${c.id}"><div class="card-top"><h3>${c.name}</h3><span class="rarity" aria-label="固有稀有度：${c.rarity}"><b aria-hidden="true">${c.mark}</b>${c.rarity}</span></div><img class="portrait" src="${asset+c.id}.detail.webp" alt="${c.name}原手绘人物" width="256" height="320"><div class="card-body"><div class="recommend ${c.stars===5?'five':''}"><div class="rec-top"><span class="rec-label">推荐指数·样例</span><span class="rec-word">${c.stars===5?'<i class="gem" aria-hidden="true"></i>':''}${c.word}</span></div>${stars(c.stars)}</div><div class="dimension"><span>路线</span><span class="route-tag">${c.route}</span></div><div class="dimension"><span>${c.id==='e08'?'生效':'组合'}</span><span class="combo-status"><i class="dots" aria-hidden="true">${c.dots}</i>${c.combo}</span></div><p class="hook">${c.hook}</p></div><div class="card-actions"><button class="select" data-id="${c.id}" aria-pressed="${selected.has(c.id)}" aria-label="${selected.has(c.id)?'移出':'加入'}对比：${c.name}">${selected.has(c.id)?'✓ 已选入对比':'＋ 选入对比'}</button></div><details data-id="${c.id}" ${opened.has(c.id)?'open':''}><summary>看${c.id==='b06'?'组合':'生效'}条件</summary><ul class="conditions">${c.conditions.map(([s,t])=>`<li><span class="check ${s==='○'?'absent':''}">${s}</span><span>${t}</span></li>`).join('')}</ul><p class="detail-note">${c.note}</p></details></article>`).join('');updateSelection();}
function updateSelection(message){document.querySelector('#count').textContent=`${selected.size}/2`;document.querySelector('#compare').disabled=selected.size!==2;document.querySelector('#selection-status').textContent=message||(selected.size===0?'点选两张，放在一起看':selected.size===1?'已选 1 张，再选一张':current().filter(c=>selected.has(c.id)).map(c=>c.name).join(' ＋ '));}
document.querySelector('#cards').addEventListener('click',e=>{const b=e.target.closest('button.select');if(!b)return;const id=b.dataset.id;if(selected.has(id))selected.delete(id);else if(selected.size<2)selected.add(id);else{updateSelection('已选满两张，请先移出一张');return;}render();document.querySelector(`button[data-id="${id}"]`).focus({preventScroll:true});});
function changeFixture(value){complete=value;document.querySelector('#missing').setAttribute('aria-pressed',String(!value));document.querySelector('#ready').setAttribute('aria-pressed',String(value));render();updateSelection(value?'已展示齐备样例 · 五星为演示值':'已展示缺搭档样例');}
document.querySelector('#missing').onclick=()=>changeFixture(false);document.querySelector('#ready').onclick=()=>changeFixture(true);
const dialog=document.querySelector('#comparison');document.querySelector('#compare').onclick=()=>{document.querySelector('#comparison-content').innerHTML=`<div class="compare-grid">${current().filter(c=>selected.has(c.id)).map(c=>`<section class="compare-column"><img src="${asset+c.id}.detail.webp" alt="${c.name}原手绘人物"><h3>${c.name}</h3><div class="compare-item ${c.stars===5?'five':''}"><small>推荐指数 · 样例</small>${stars(c.stars)}<strong>${c.word}</strong></div><div class="compare-item"><small>固有稀有度</small>${c.mark} ${c.rarity}</div><div class="compare-item"><small>路线</small>${c.route}</div><div class="compare-item"><small>${c.id==='e08'?'生效门槛':'组合条件'}</small>${c.combo}<br>${c.hook}</div></section>`).join('')}</div>`;dialog.showModal();};document.querySelector('#close-compare').onclick=()=>dialog.close();render();
